reproduction.command:
bun -e 'import { canonicalSha256, sha256Hex } from "./src/canonical";
import { codeIdentity, excludeGroups, loadDataset, loadExclusions } from "./scripts/benchmarks/io";
import { selectSplit, selectQuestions } from "./scripts/benchmarks/datasets";
import { loadUnitReport } from "./scripts/benchmarks/extract";
import { runRetrieval } from "./scripts/benchmarks/runner";
const started = performance.now();
const sourcePath = ".cache/benchmarks/runs/longmemeval-memory-strategy-fresh-v1.json";
const unitPath = ".cache/benchmarks/runs/longmemeval-fresh-units-v6.json";
const exclusionPaths = ["benchmarks/results/longmemeval-s-heldout.json", "benchmarks/results/longmemeval-s-heldout-v2.json", "benchmarks/results/longmemeval-s-reader-heldout.json"];
const sourceBytes = await Bun.file(sourcePath).bytes();
const source = JSON.parse(new TextDecoder().decode(sourceBytes));
const m = source.manifest;
const { files, ...code } = await codeIdentity();
const exclusions = await loadExclusions(exclusionPaths, m.dataset);
if (canonicalSha256(exclusions.reports) !== canonicalSha256(m.exclusions)) throw new Error("Exclusion reports changed");
const selected = selectQuestions(excludeGroups(selectSplit(await loadDataset(m.dataset), m.split, m.seed), exclusions.groups), m.limit, m.seed);
if (JSON.stringify(selected.questions.map((q) => q.id)) !== JSON.stringify(m.selectedQuestions)) throw new Error("Question selection changed");
if (JSON.stringify(selected.corpora.map((c) => c.id)) !== JSON.stringify(m.selectedCorpora)) throw new Error("Corpus selection changed");
if (selected.corpora.some((c) => exclusions.groups.has(c.groupId))) throw new Error("Excluded family selected");
const memory = await loadUnitReport(unitPath, m.dataset, m.split, m.seed, selected.corpora);
if (memory.provenance.reportSha256 !== source.memoryUnits.reportSha256) throw new Error("Unit report changed");
const replay = await runRetrieval(selected, m.systems, m.budget, m.seed, memory);
const key = (r) => `${r.questionId}:${r.system}`;
const before = new Map(source.rows.map((r) => [key(r), r]));
const after = new Map(replay.rows.map((r) => [key(r), r]));
if (before.size !== source.rows.length || after.size !== replay.rows.length) throw new Error("Duplicate context key");
const contexts = (rows) => rows.map((r) => [key(r), r.contextSha256, r.contextBytes]).sort((a, b) => a[0].localeCompare(b[0]));
const comparison = {
  originalRows: source.rows.length, replayRows: replay.rows.length,
  missingRows: [...before.keys()].filter((k) => !after.has(k)).length,
  extraRows: [...after.keys()].filter((k) => !before.has(k)).length,
  contextHashMismatches: replay.rows.filter((r) => before.get(key(r))?.contextSha256 !== r.contextSha256).length,
  contextByteCountMismatches: replay.rows.filter((r) => before.get(key(r))?.contextBytes !== r.contextBytes).length,
  originalContextSetSha256: canonicalSha256(contexts(source.rows)),
  replayContextSetSha256: canonicalSha256(contexts(replay.rows)),
  unitPreparationRecordedForEveryCorpus: replay.ingestion.every((i) => i.unitIndexes.blocks !== undefined && i.unitIndexes.facts !== undefined)
};
const passed = comparison.originalRows === 72 && comparison.replayRows === 72
  && comparison.missingRows === 0 && comparison.extraRows === 0
  && comparison.contextHashMismatches === 0 && comparison.contextByteCountMismatches === 0
  && comparison.originalContextSetSha256 === comparison.replayContextSetSha256
  && comparison.unitPreparationRecordedForEveryCorpus;
console.log(JSON.stringify({
  protocol: "oh.memory-context-replay.v1", recordedAt: new Date().toISOString(), status: passed ? "passed" : "failed",
  purpose: "Verify fresh reader contexts after final integration with current main.",
  code, sourceReport: { path: sourcePath, sha256: sha256Hex(sourceBytes) },
  memoryUnitReport: { path: unitPath, sha256: memory.provenance.reportSha256 },
  dataset: m.dataset, split: m.split, seed: m.seed, questions: selected.questions.length, corpora: selected.corpora.length,
  systems: m.systems, budget: m.budget, selectionSha256: m.selectionSha256, excludedFamilies: exclusions.groups.size,
  exclusionReports: exclusionPaths.map((path, index) => ({ path, ...exclusions.reports[index] })),
  comparison, execution: { exitCode: passed ? 0 : 1, wallSeconds: (performance.now() - started) / 1000, paidCalls: 0, stores: "in-memory" },
  qualifications: ["This verifies rendered context stability, not unchanged model responses or new answer-quality evidence."]
}, null, 2));
if (!passed) process.exit(1);'
